import {
  createAudioPlayer,
  setAudioModeAsync,
  type AudioPlayer,
} from "expo-audio";

// Generated by scripts/generate-beep.mjs.
const BEEP = require("../../assets/sounds/scan-beep.wav");

// One player for the app's lifetime: the beep is tiny and plays on every scan,
// so it is never released rather than reloaded per screen.
let player: AudioPlayer | null = null;

function beepPlayer(): AudioPlayer {
  if (!player) {
    // Mix with the shop's music instead of pausing it, and stay quiet when the
    // phone is on silent (the vibration still confirms the scan).
    setAudioModeAsync({
      playsInSilentMode: false,
      interruptionMode: "mixWithOthers",
    }).catch(() => {});
    player = createAudioPlayer(BEEP, { keepAudioSessionActive: true });
  }
  return player;
}

/** Loads the beep ahead of the first scan so it plays without a delay. */
export function warmUpBeep() {
  try {
    beepPlayer();
  } catch {
    // Sound is a nicety: a device without audio must never break a sale.
  }
}

/** The till scanner's short confirmation tone. */
export function beep() {
  try {
    const p = beepPlayer();
    p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // Sound is a nicety: a device without audio must never break a sale.
  }
}
